#include <stdio.h>
int main(void) {
    FILE *w = fopen("e.txt", "w");
    fputs("AB\n", w);
    fclose(w);
    FILE *r = fopen("e.txt", "r");
    int c; int count = 0;
    /* 正确：以「读取失败」为循环终止条件，而不是以 feof() 判断 */
    while ((c = fgetc(r)) != EOF) { count++; }
    /* feof 只在「一次读操作越过文件尾」之后才为真 */
    printf("chars read=%d feof=%d\n", count, feof(r) ? 1 : 0);
    fclose(r);
    return 0;
}
